public class Product {
    private String name;
    private double price;

    public Product(String name, double price) {
        this.name = name;
        this.price = price;
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public String describe() {
        return name + " 售价 " + price + " 元";
    }
}

public class Main {
    public static void main(String[] args) {
        Product tea = new Product("龙井茶", 128.0);
        Product cup = new Product("陶瓷杯", 39.5);

        System.out.println(tea.describe());
        System.out.println(cup.describe());
        System.out.println("两个实例的名字相同吗: " + tea.getName().equals(cup.getName()));
    }
}
